// FILE: core.h
// PURPOSE: Public API for the core backend logic. Handles donor records,
//          eligibility checks, blood stock management, and file persistence.

#ifndef CORE_H
#define CORE_H

// 1. HEADER INCLUDES
#include "models.h"   // Imports our custom data structures (Donor, Date, BloodInventory, etc.)
#include <stddef.h>   // Provides 'size_t', a safe unsigned type for array sizes and loop counters

// 2. GLOBAL ERROR BUFFER
// Stores the latest error message generated by core functions so the UI can display what went wrong.
// 'extern' means this array is declared here, while its actual memory is allocated in core.c.
extern char core_last_error[256];

// 3. SYSTEM & UTILITY FUNCTIONS
bool core_init(BloodInventory *inventory);                  // Initializes the blood inventory at startup so the program runs safely
int  core_find_blood_group(const char *group);              // Returns the array index (0-7) for a blood group string (e.g., "O+"), or -1 if invalid
void core_get_today(Date *today);                           // Fetches the system's current date and stores it in 'today'

// 4. ELIGIBILITY & DONOR LOOKUP
bool core_check_eligibility(int age, double weight, bool has_donated, const Date *last, const Date *today); // Checks if a donor meets age, weight, and waiting-period rules
bool core_get_all_donors(Donor *records, size_t capacity, size_t *count); // Loads donor records into an array up to 'capacity' and updates 'count'
bool core_get_donor(uint32_t id, Donor *result);            // Searches for a single donor by ID and copies their details into 'result'

// 5. DONOR DATABASE OPERATIONS (CRUD)
bool core_add_donor(const Donor *donor);                    // Appends a new donor record to the database file
bool core_update_donor(const Donor *donor);                 // Overwrites an existing donor's record with updated details
bool core_delete_donor(uint32_t id);                        // Removes a donor record from the file using their ID

// 6. BLOOD INVENTORY MANAGEMENT
bool core_add_units(BloodInventory *inventory, const char *group, uint32_t units);    // Adds donated blood units to a specific blood group
bool core_deduct_units(BloodInventory *inventory, const char *group, uint32_t units); // Deducts blood units when fulfilling a hospital request

// 7. DATA PERSISTENCE (FILE I/O)
bool core_save_inventory(const BloodInventory *inventory);  // Saves current in-memory blood stock data to the hard drive
bool core_load_inventory(BloodInventory *inventory);  // Loads saved blood stock data from the hard drive back into memory

#endif // End of CORE_H header guard